enum SkillsAction: Codable, Hashable, Sendable, CaseIterable, RawRepresentable {
    case list
    case search
    case install
    case browse
    case inspect
    /// A value this contract doesn't know, kept as sent.
    case unknown(String)

    static let allCases: [SkillsAction] = [.list, .search, .install, .browse, .inspect]

    init(rawValue: String) {
        switch rawValue {
        case "list": self = .list
        case "search": self = .search
        case "install": self = .install
        case "browse": self = .browse
        case "inspect": self = .inspect
        default: self = .unknown(rawValue)
        }
    }

    var rawValue: String {
        switch self {
        case .list: return "list"
        case .search: return "search"
        case .install: return "install"
        case .browse: return "browse"
        case .inspect: return "inspect"
        case let .unknown(value): return value
        }
    }

    init(from decoder: Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

