    var unlocked: Bool?
}

/// One `verification_events` row (`agent/verification_evidence.py`).
struct VerificationEvidenceRow: Codable, Hashable, Sendable {
    var id: Int?
    var createdAt: String?
    var sessionId: String?
    var cwd: String?
    var root: String?
    var command: String?
    var canonicalCommand: String?
    var kind: String?
    var scope: String?
    var status: String?
    var exitCode: Int?
    var outputSummary: String?
    /// Members outside the contract, kept as sent.
    var extras: [String: JSONValue] = [:]

    enum CodingKeys: String, CodingKey, CaseIterable {
        case id
        case createdAt = "created_at"
        case sessionId = "session_id"
        case cwd
        case root
        case command
        case canonicalCommand = "canonical_command"
        case kind
        case scope
        case status
        case exitCode = "exit_code"
        case outputSummary = "output_summary"
    }
}

extension VerificationEvidenceRow {
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try container.decodeIfPresent(Int.self, forKey: .id)
        self.createdAt = try container.decodeIfPresent(String.self, forKey: .createdAt)
        self.sessionId = try container.decodeIfPresent(String.self, forKey: .sessionId)
        self.cwd = try container.decodeIfPresent(String.self, forKey: .cwd)
        self.root = try container.decodeIfPresent(String.self, forKey: .root)
        self.command = try container.decodeIfPresent(String.self, forKey: .command)
        self.canonicalCommand = try container.decodeIfPresent(String.self, forKey: .canonicalCommand)
        self.kind = try container.decodeIfPresent(String.self, forKey: .kind)
        self.scope = try container.decodeIfPresent(String.self, forKey: .scope)
        self.status = try container.decodeIfPresent(String.self, forKey: .status)
        self.exitCode = try container.decodeIfPresent(Int.self, forKey: .exitCode)
        self.outputSummary = try container.decodeIfPresent(String.self, forKey: .outputSummary)
        self.extras = try decoder.extraValues(excluding: Set(CodingKeys.allCases.map(\.stringValue)))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(self.id, forKey: .id)
        try container.encodeIfPresent(self.createdAt, forKey: .createdAt)
        try container.encodeIfPresent(self.sessionId, forKey: .sessionId)
        try container.encodeIfPresent(self.cwd, forKey: .cwd)
        try container.encodeIfPresent(self.root, forKey: .root)
        try container.encodeIfPresent(self.command, forKey: .command)
        try container.encodeIfPresent(self.canonicalCommand, forKey: .canonicalCommand)
        try container.encodeIfPresent(self.kind, forKey: .kind)
        try container.encodeIfPresent(self.scope, forKey: .scope)
        try container.encodeIfPresent(self.status, forKey: .status)
        try container.encodeIfPresent(self.exitCode, forKey: .exitCode)
        try container.encodeIfPresent(self.outputSummary, forKey: .outputSummary)
        try encoder.encodeExtras(self.extras, excluding: Set(CodingKeys.allCases.map(\.stringValue)))
    }
}

/// `verification_status()`: `disabled` / `not_applicable` / `unverified` / `stale` or the latest event's own
/// status; `root` and friends only once a workspace was identified.
struct VerificationStatusInfo: Codable, Hashable, Sendable {
    var status: String
    var evidence: VerificationEvidenceRow?
    var root: String?
    var sessionId: String?
    var changedPaths: [String]?

    enum CodingKeys: String, CodingKey {
        case status
        case evidence
        case root
        case sessionId = "session_id"
        case changedPaths = "changed_paths"
    }
}

struct VerificationStatusParams: Codable, Hashable, Sendable {
    var profile: String?
    var sessionId: String?
    var sessionKey: String?
    var cwd: String?

    enum CodingKeys: String, CodingKey {
        case profile
        case sessionId = "session_id"
        case sessionKey = "session_key"
        case cwd
    }
}

struct VerificationStatusResult: Codable, Hashable, Sendable {
    var verification: VerificationStatusInfo
}

struct WaitBarrierTarget: Codable, Hashable, Sendable {
    var type: WaitBarrierTargetType
    var target: IntOrString
    var reason: String?
}

struct WaitBarrierUntil: Codable, Hashable, Sendable {
    var type: String = "until"
    var untilAt: Double
    var reason: String?

    enum CodingKeys: String, CodingKey {
        case type
        case untilAt = "until_at"
        case reason
    }
}
